/**
 * Normalize a bracketed placeholder token to its field key, e.g.
 * "[PARTY A LEGAL NAME]" -> "PARTY_A_LEGAL_NAME",
 * "[GOODS / SERVICES / BOTH]" -> "GOODS_SERVICES_BOTH".
 */
export function placeholderKey(token: string): string {
  return token
    .replace(/[^A-Z0-9]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .toUpperCase();
}

/** Value rendered when a field was left blank / does not apply. */
export const NOT_APPLICABLE = 'Not applicable';

/**
 * Substitute every [TOKEN] in the template with its value. Blank or
 * missing values render as NOT_APPLICABLE so the completed agreement
 * never shows a raw placeholder.
 */
export function substituteAgreementFields(
  template: string,
  values: Record<string, string | undefined | null>,
  fallback: string = NOT_APPLICABLE,
): string {
  return template.replace(/\[([^\]]+)\]/g, (_match, token: string) => {
    const raw = values[placeholderKey(token)];
    const value = raw === undefined || raw === null ? '' : String(raw).trim();
    return value === '' ? fallback : value;
  });
}

/** Extract every distinct placeholder token present in a template. */
export function templatePlaceholders(template: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const m of template.matchAll(/\[([^\]]+)\]/g)) {
    const token = m[1];
    if (!seen.has(token)) {
      seen.add(token);
      out.push(token);
    }
  }
  return out;
}
